			var src: Long = s!!.sidx(donor, m)
			var dst: Long = s!!.sidx(receiver, m)
			if ((java.lang.Long.compareUnsigned(src, (s!!.washoff_conc_old)!!.size()) < 0) && (java.lang.Long.compareUnsigned(dst, (s!!.runon_qual_rate)!!.size()) < 0)) {
				(s!!.runon_qual_rate)!!.a!![dst.toInt()] += (q * (s!!.washoff_conc_old)!!.a!![src.toInt()]) * 28.317
			}
			m++
		}
	}

	@JvmStatic fun deliver(ctx: SimulationContext?, p: Double) {
		var s: MsxSurfaceData? = (ctx!!.reactions)!!.surface
		if (!(s!!.active())) {
			return
		}
		var rx: ReactionData? = ctx!!.reactions
		var nm: Int = rx!!.n_species()
		if ((nm != s!!.n_species) || (ctx!!.n_nodes() <= 0)) {
			return
		}
		var want: Long = (ctx!!.n_nodes()).toLong() * nm.toLong()
		if ((rx!!.msx_ext_mass_in)!!.size() != want) {
			(rx!!.msx_ext_mass_in)!!.assign_ul_T(want, 0.0)
		}
		var i: Int = 0
		__L1@ while (i < ctx!!.n_subcatches()) {
			var ui: Long = i.toLong()
			var out_node: Int = ((ctx!!.subcatches)!!.outlet_node)!!.a!![ui.toInt()]
			if ((out_node < 0) || (out_node >= ctx!!.n_nodes())) {
				i++
				continue@__L1
			}
			var f: Double = ctx!!.runoff_interp_f
			var f1: Double = 1.0 - f
			var q_old: Double = ((ctx!!.subcatches)!!.old_runoff)!!.a!![ui.toInt()]
			var q_new: Double = ((ctx!!.subcatches)!!.runoff)!!.a!![ui.toInt()]
			var q: Double = (f1 * q_old) + (f * q_new)
			if (q <= 0.0) {
				i++
				continue@__L1
			}
			var has_old: Boolean = (s!!.washoff_conc_old)!!.size() == (s!!.washoff_conc)!!.size()
			var base: Long = out_node.toLong() * nm.toLong()
			var m: Int = 0
			__L2@ while (m < nm) {
				var si: Long = s!!.sidx(i, m)
				var c_new: cpp.RefD.Cell = cpp.RefD.Cell((s!!.washoff_conc)!!.a!![si.toInt()])
				var c_old: Double = (if (has_old) cpp.RefD.Arr((s!!.washoff_conc_old)!!.a, si.toInt()) else c_new)!!.get()
				var mass_rate: Double = (f1 * (q_old * c_old)) + (f * (q_new * c_new.v))
				if (mass_rate > 0.0) {
					(rx!!.msx_ext_mass_in)!!.a!![(base + m.toLong()).toInt()] += mass_rate
				}
				m++
			}
			i++
		}
		if ((s!!.lid_drain_load)!!.size() == want) {
			var f_2: Double = ctx!!.runoff_interp_f
			var f1_2: Double = 1.0 - f_2
			var has_old_2: Boolean = (s!!.lid_drain_load_old)!!.size() == want
			var j: Int = 0
			__L3@ while (j < ctx!!.n_nodes()) {
				var uj: Long = j.toLong()
				var v_new: Double = if (java.lang.Long.compareUnsigned(uj, ((ctx!!.nodes)!!.lid_drain_qual_vol)!!.size()) < 0) ((ctx!!.nodes)!!.lid_drain_qual_vol)!!.a!![uj.toInt()] else 0.0
				var v_old: Double = if (java.lang.Long.compareUnsigned(uj, ((ctx!!.nodes)!!.lid_drain_qual_vol_old)!!.size()) < 0) ((ctx!!.nodes)!!.lid_drain_qual_vol_old)!!.a!![uj.toInt()] else 0.0
				if (((f1_2 * v_old) + (f_2 * v_new)) <= 0.0) {
					j++
					continue@__L3
				}
				var m_2: Int = 0
				__L4@ while (m_2 < nm) {
					var k: Long = (uj * nm.toLong()) + m_2.toLong()
					var w_new: Double = (s!!.lid_drain_load)!!.a!![k.toInt()]
					var w_old: Double = if (has_old_2) (s!!.lid_drain_load_old)!!.a!![k.toInt()] else 0.0
					var load: Double = (f1_2 * w_old) + (f_2 * w_new)
					if (load > 0.0) {
						(rx!!.msx_ext_mass_in)!!.a!![k.toInt()] += load
					}
					m_2++
				}
				j++
			}
		}
	}

